<script setup>
import {ref,computed,onMounted,nextTick} from 'vue'
import {api} from './api.mjs'
import FileRecycle from './PermanentDeletion.vue'
const emit=defineEmits(['close','open','copy','changed'])
const rows=ref([]),batches=ref([]),selected=ref([]),tab=ref('business'),query=ref(''),working=ref(false),error=ref(''),message=ref(''),plan=ref(null),dialog=ref(null)
const previewSection=ref(null)
const filtered=computed(()=>rows.value.filter(row=>tab.value==='trash'?row.trashed:!row.trashed&&(tab.value==='development'?row.purpose==='development':row.purpose!=='development')).filter(row=>!query.value||row.name.includes(query.value)))
const available=computed(()=>filtered.value.filter(row=>!row.recycleBlocked.length))
const looseTrash=computed(()=>filtered.value.filter(row=>!batches.value.some(batch=>batch.schemes.some(item=>item.familyId===row.familyId))))
const trashObjects=computed(()=>rows.value.filter(row=>row.trashed).map(row=>({kind:'scheme',id:row.id,name:row.name})))
function batchObjects(batch){const families=new Set(batch.schemes.map(row=>row.familyId));return trashObjects.value.filter(object=>rows.value.some(row=>row.id===object.id&&families.has(row.familyId)))}
function toggleBatch(batch,isSelected,toggle){const objects=batchObjects(batch),on=!objects.every(isSelected);for(const object of objects)if(isSelected(object)!==on)toggle(object)}
function fileStatus(batch){return rows.value.some(row=>batch.schemes.some(item=>item.familyId===row.familyId)&&row.fileRecycleStatus==='recycled')}
async function filesChanged(){message.value='本地文件已送入Windows回收站。需要恢复时，先在系统回收站还原文件。';await load();emit('changed')}
const stateNames={succeeded:'已完成',failed:'失败',cancelled:'已停止',interrupted:'已中断',queued:'排队中',running:'计算中',stopping:'正在停止'}
async function load(){const data=await api('scheme-management');rows.value=data.schemes;batches.value=data.recycleBatches}
function changeTab(value){tab.value=value;selected.value=[];plan.value=null;error.value='';message.value=''}
function toggleAll(event){selected.value=event.target.checked?available.value.map(row=>row.id):[];plan.value=null}
async function preview(){working.value=true;error.value='';try{plan.value=await api('schemes/recycle-preview',{schemeIds:selected.value});await nextTick();previewSection.value?.scrollIntoView({block:'end'})}catch(e){error.value=e.message}finally{working.value=false}}
async function recycle(){working.value=true;error.value='';try{const schemeIds=plan.value.schemeIds;const result=await api('schemes/recycle',{schemeIds,token:plan.value.token});message.value=`已将${result.schemeCount}个方案及${result.resultCount}份关联结果移入回收站。`;selected.value=[];plan.value=null;await load();emit('changed',{schemeIds,trashed:true});tab.value='trash'}catch(e){error.value=e.message}finally{working.value=false}}
async function restore(batch){working.value=true;error.value='';try{await api('schemes/restore-batch',{batchId:batch.id});message.value='方案及本次一并回收的结果已恢复。';await load();emit('changed')}catch(e){error.value=e.message}finally{working.value=false}}
async function restoreLoose(row){working.value=true;error.value='';try{await api('schemes/'+row.id+'/metadata',{trashed:false});message.value='方案已恢复。';await load();emit('changed')}catch(e){error.value=e.message}finally{working.value=false}}
function open(row){emit('open',row)}
onMounted(async()=>{working.value=true;try{await load();await nextTick();dialog.value?.focus()}catch(e){error.value=e.message}finally{working.value=false}})
</script>

<template>
 <Teleport to="body"><div class="scheme-manager-shade" @click.self="!working&&emit('close')"><section ref="dialog" class="scheme-manager" role="dialog" aria-modal="true" aria-labelledby="scheme-manager-title" tabindex="-1" @keydown.esc="!working&&emit('close')">
  <header><div><small>方案与计算成果</small><h2 id="scheme-manager-title">管理方案</h2></div><button :disabled="working" aria-label="关闭方案管理" @click="emit('close')">×</button></header>
  <nav aria-label="方案目录"><button v-for="item in [['business','已保存方案'],['development','开发试验'],['trash','回收站']]" :key="item[0]" :class="{active:tab===item[0]}" :disabled="working" @click="changeTab(item[0])">{{item[1]}}</button><input v-if="tab!=='trash'" v-model="query" aria-label="检索方案名称" placeholder="检索方案名称" :disabled="working"></nav>
  <p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="message" class="message success" role="status">{{message}}</p>
  <template v-if="tab!=='trash'">
   <div class="scheme-manager-toolbar"><label><input type="checkbox" aria-label="全选可回收方案" :checked="available.length>0&&available.every(row=>selected.includes(row.id))" :disabled="working||!available.length" @change="toggleAll">全选可回收方案</label><span>已选 {{selected.length}} 个</span><button :disabled="working||!selected.length" @click="preview">移入回收站（含关联结果）</button></div>
   <div class="scheme-manager-table"><table><thead><tr><th>选择</th><th>方案</th><th>最近保存</th><th>计算结果</th><th>操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id" :data-scheme="row.id"><td><input type="checkbox" v-model="selected" :value="row.id" :aria-label="'选择方案 '+row.name" :disabled="working||!!row.recycleBlocked.length" @change="plan=null"></td><td><b>{{row.name}}</b><small v-if="row.current" class="current">当前采用</small><small v-else-if="row.recycleBlocked.length">{{row.recycleBlocked.join('；')}}</small><details v-if="row.revisionCount>1" class="save-history"><summary>保存历史</summary><small>保留 {{row.revisionCount}} 次设置，最近为第 {{row.payload.revision||1}} 次保存。</small></details></td><td>{{row.created_at?.slice(0,10)||'—'}}</td><td>{{row.resultCount}} 份</td><td class="row-actions"><button :disabled="working" @click="open(row)">打开方案</button><button :disabled="working" @click="emit('copy',row)">复制方案</button></td></tr></tbody></table><p v-if="!filtered.length" class="empty">{{working?'正在读取方案…':'暂无方案。'}}</p></div>
   <section v-if="plan" ref="previewSection" class="scheme-recycle-preview" aria-label="回收确认"><h3>确认回收内容</h3><p>{{plan.schemeCount}} 个方案及 {{plan.resultCount}} 份关联结果，均可恢复。</p><ul><li v-for="item in plan.items" :key="item.familyId"><b>{{item.name}}</b> · {{item.revisionCount}} 个修订<span v-if="item.recycleBlocked.length" class="blocked">{{item.recycleBlocked.join('；')}}</span></li></ul><details v-if="plan.results.length"><summary>查看关联结果（{{plan.results.length}}份）</summary><ul><li v-for="result in plan.results" :key="result.id">{{result.name||result.id}} · {{stateNames[result.status]||result.status}}{{result.trashed?' · 原已回收':''}}</li></ul></details><div class="preview-actions"><button :disabled="working" @click="plan=null">取消</button><button class="primary" :disabled="working||plan.blocked" @click="recycle">确认移入回收站</button></div></section>
  </template>
  <template v-else><p class="muted">可恢复方案与结果，也可勾选后将本地文件送入Windows回收站。</p><FileRecycle :objects="trashObjects" :busy="working" @changed="filesChanged"><template #rows="{isSelected,toggle}"><article v-for="batch in batches" :key="batch.id" class="scheme-trash-batch"><label><input type="checkbox" :aria-label="'整理本地文件 '+batch.schemes.map(row=>row.name).join('、')" :checked="batchObjects(batch).length>0&&batchObjects(batch).every(isSelected)" :disabled="working||fileStatus(batch)" @change="toggleBatch(batch,isSelected,toggle)"><span><b>{{batch.schemes.map(item=>item.name).join('、')}}</b><small>{{batch.schemes.length}} 个方案 · {{batch.resultIds.length}} 份结果 · {{batch.createdAt.slice(0,10)}}</small><small v-if="fileStatus(batch)" class="current">文件已在Windows回收站</small></span></label><button :disabled="working" @click="restore(batch)">恢复方案与结果</button></article><article v-for="row in looseTrash" :key="row.id" class="scheme-trash-batch"><label><input type="checkbox" :aria-label="'整理本地文件 '+row.name" :checked="isSelected({kind:'scheme',id:row.id})" :disabled="working||row.fileRecycleStatus==='recycled'" @change="toggle({kind:'scheme',id:row.id})"><span><b>{{row.name}}</b><small>{{row.fileRecycleStatus==='recycled'?'文件已在Windows回收站':'此前回收的方案'}}</small></span></label><button :disabled="working" @click="restoreLoose(row)">恢复方案</button></article><p v-if="!batches.length&&!looseTrash.length" class="empty">回收站为空。</p></template></FileRecycle></template>
 </section></div></Teleport>
</template>

<style scoped>
.scheme-trash-batch>label{display:flex;align-items:flex-start;gap:13px}.scheme-trash-batch>label>input{margin-top:3px}.save-history{font-size:11px;color:var(--muted);margin-top:7px}.save-history summary{cursor:pointer}.scheme-trash-batch .current{color:#277f89}
.scheme-manager-shade{position:fixed;inset:0;z-index:145;background:#071e2c99;display:grid;place-items:center;padding:24px}.scheme-manager{width:min(1040px,100%);max-height:calc(100dvh - 48px);overflow:auto;padding:28px 32px;background:var(--panel,#fff);border-radius:10px;box-shadow:0 20px 70px #001a354d;outline:none}.scheme-manager>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.scheme-manager header small,.scheme-manager td small,.scheme-trash-batch small{display:block;color:var(--muted);font-size:12px}.scheme-manager h2{font-size:23px;margin:6px 0}.scheme-manager nav{display:flex;gap:8px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:14px}.scheme-manager nav input{margin-left:auto;width:220px}.scheme-manager nav .active{background:#e8f3f2;border-color:#277f89;color:#226f78}.scheme-manager-toolbar{display:flex;align-items:center;gap:16px;margin:20px 0 12px;font-size:13px}.scheme-manager-toolbar label{display:flex;align-items:center;gap:8px}.scheme-manager-toolbar>span{color:var(--muted);margin-right:auto}.scheme-manager input[type=checkbox]{accent-color:#277f89;width:16px;height:16px}.scheme-manager-table{overflow:auto;max-height:45dvh}.scheme-manager table{width:100%;min-width:680px}.scheme-manager th,.scheme-manager td{padding:13px 10px;text-align:left;border-bottom:1px solid var(--line)}.scheme-manager th{font-size:12px;color:var(--muted);background:#f0f6f5}.scheme-manager td{font-size:13px}.scheme-manager td>b{font-weight:500}.scheme-manager td small{margin-top:6px}.scheme-manager td .current{color:#277f89}.row-actions{white-space:nowrap}.row-actions button{margin-right:6px;font-size:12px}.scheme-recycle-preview{padding:18px 20px;background:#f0f6f5;border:1px solid #cfdfdf;margin-top:18px}.scheme-recycle-preview h3{font-size:16px;margin:0 0 12px}.scheme-recycle-preview p,.scheme-recycle-preview li,.scheme-recycle-preview summary{font-size:13px;line-height:1.8}.scheme-recycle-preview ul{padding-left:20px;max-height:190px;overflow:auto}.scheme-recycle-preview .blocked{color:#a24b27;margin-left:12px}.preview-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.scheme-trash-batch{display:flex;gap:20px;justify-content:space-between;align-items:center;padding:16px 0;border-bottom:1px solid var(--line)}.scheme-trash-batch small{margin-top:7px}.scheme-trash-batch b{font-size:14px;font-weight:500}.scheme-manager .empty{padding:28px 0;color:var(--muted)}@media(max-width:760px){.scheme-manager-shade{padding:10px}.scheme-manager{padding:20px;max-height:calc(100dvh - 20px)}.scheme-manager nav{flex-wrap:wrap}.scheme-manager nav input{margin-left:0;width:100%}.scheme-manager-toolbar{flex-wrap:wrap}.scheme-manager-toolbar>button{width:100%}.scheme-trash-batch{align-items:flex-start}}
</style>
